import{_ as o,o as r,c as a,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 23 章 平台全景：一支 AI 团队的全套装备（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第23章 平台全景：一支 AI 团队的全套装备（易懂版）.md","filePath":"easy/第23章 平台全景：一支 AI 团队的全套装备（易懂版）.md"}'),n={name:"easy/第23章 平台全景：一支 AI 团队的全套装备（易懂版）.md"};function s(d,t,l,i,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="第-23-章-平台全景-一支-ai-团队的全套装备-易懂版" tabindex="-1">第 23 章 平台全景：一支 AI 团队的全套装备（易懂版） <a class="header-anchor" href="#第-23-章-平台全景-一支-ai-团队的全套装备-易懂版" aria-label="Permalink to &quot;第 23 章 平台全景：一支 AI 团队的全套装备（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 <a href="./../bluebook/第五篇 平台能力全景/第 23 章 平台全景：一支 AI 团队的全套装备.html">第 23 章 平台全景：一支 AI 团队的全套装备（完整版）</a>。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>把&quot;我到底有啥装备&quot;一次说清：技能、专家、团队模板、扩展、多端入口，全在这。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>一个人干活，靠的是<strong>工具箱</strong>：螺丝刀、电钻、卷尺。 一支团队干活，靠的是<strong>装备库</strong>：工具、专业师傅、现成的作业流程、还能叫外援、还有对讲机随时联系。</p><p><strong>我背后就有这样一个装备库。</strong> 你不需要记住所有东西，只需要知道&quot;遇到什么事，该喊哪件装备&quot;。</p><h2 id="全套装备的七层-从上往下看" tabindex="-1">全套装备的七层（从上往下看） <a class="header-anchor" href="#全套装备的七层-从上往下看" aria-label="Permalink to &quot;全套装备的七层（从上往下看）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>是什么</th><th>你什么时候会用到</th></tr></thead><tbody><tr><td><strong>入口层</strong></td><td>电脑客户端、局域网网页、手机</td><td>想在手机上看进度</td></tr><tr><td><strong>团队层</strong></td><td>AI 团队、团队模板</td><td>一件事要多人分工</td></tr><tr><td><strong>专家层</strong></td><td>11 位内置专家助手</td><td>想让&quot;某类人&quot;来把关</td></tr><tr><td><strong>技能层</strong></td><td>内置技能库（出图、出片、交文档）</td><td>要图片、视频、Word、PPT</td></tr><tr><td><strong>工具层</strong></td><td>读写文件、执行命令、搜索</td><td>每天都会用到</td></tr><tr><td><strong>自动化层</strong></td><td>定时任务、自动流水线</td><td>想让它每天自己跑</td></tr><tr><td><strong>记忆层</strong></td><td>记忆文件、项目上下文</td><td>想让它越来越懂你</td></tr></tbody></table><h2 id="装备从哪来-三个来源" tabindex="-1">装备从哪来（三个来源） <a class="header-anchor" href="#装备从哪来-三个来源" aria-label="Permalink to &quot;装备从哪来（三个来源）&quot;">​</a></h2><ul><li><strong>自带的</strong>：装好就有，开箱即用（内置技能、内置专家、团队模板）；</li><li><strong>自建的</strong>：你把经验沉淀成 Skill 或自定义专家（见第 17、26 章）；</li><li><strong>外部装的</strong>：从市场装扩展、连 MCP 工具（见第 28 章）。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>你问：&quot;我想给新产品做一套宣传物料。&quot; 我拆开装备库：<strong>第 24 章出图/出片</strong> → <strong>第 25 章交一份 PPT</strong> → <strong>第 26 章请专家审文案</strong> → <strong>第 27 章用团队模板并行推进</strong>。</p></blockquote><p>你看，你只说了一句话，我是在<strong>从装备库里挑组合</strong>。</p><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 以为要背下所有技能名——<strong>记不住就问&quot;你能干啥&quot;，我列给你</strong>；</li><li>❌ 什么活都自己硬扛——<strong>该叫专家叫专家，该拉团队拉团队</strong>；</li><li>❌ 装一堆扩展不用——<strong>装备要进流程才算数</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>我不是一个聊天框，而是一支 AI 团队的全套装备；你说需求，我挑组合。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>想一件你最近要做的杂事，问自己：<strong>这事儿需要&quot;出图&quot;吗？需要&quot;专家&quot;吗？需要&quot;重复跑&quot;吗？</strong> 答案就是你要用的那一层装备。</p><p>👉 [下一章：内置技能库（一），图像与视频生成（易懂版）](第24章 内置技能库（一）：图像与视频生成（易懂版）.md)</p>',21)])])}const c=o(n,[["render",s]]);export{_ as __pageData,c as default};
